import os

import pytest

import gil_study


@pytest.fixture(scope="module")
def results():
    return gil_study.run_all()


def test_cpu_threads_no_real_speedup(results):
    """4 threads on pure-Python CPU work: within 0.7x-1.6x of 1 thread."""
    ratio = results["cpu_4_threads"] / results["cpu_1_thread"]
    assert 0.7 <= ratio <= 1.6, f"ratio={ratio:.2f}, expected GIL serialisation"


@pytest.mark.skipif(
    (os.cpu_count() or 0) < 4,
    reason="need at least 4 CPUs to compare 1 thread vs 4 processes",
)
def test_cpu_processes_beat_threads(results):
    """4 processes must beat 1 thread by more than 1.8x."""
    assert results["cpu_4_processes"] is not None
    ratio = results["cpu_1_thread"] / results["cpu_4_processes"]
    assert ratio > 1.8, f"speedup x{ratio:.2f}, expected > 1.8x from real parallelism"


def test_io_threads_scale(results):
    """16 threads on latency-bound IO: beat 1 thread by more than 5x."""
    ratio = results["io_1_thread"] / results["io_16_threads"]
    assert ratio > 5, f"speedup x{ratio:.2f}, expected > 5x while the GIL is released"
